1	#!/usr/bin/env node
2	// Prov Guard —— 软件供应链证明与完整性校验工具（零依赖，Node >= 18）。
3	//
4	// 子命令：
5	//   keygen   --key-dir <dir> [--name <prefix>]
6	//   generate --artifact <path> --key <private-key> --out <dir>
7	//   verify   --artifact <path> --proof <file> --signature <file> --key <public-key>
8	//            [--sbom <file> --sbom-signature <file>] [--policy <policy.json>]
9	//
10	// 所有输出均为 UTF-8；成功结果写 stdout，错误结果写 stderr。
11	
12	import {
13	  createHash,
14	  createPrivateKey,
15	  createPublicKey,
16	  generateKeyPairSync,
17	  sign as cryptoSign,
18	  verify as cryptoVerify,
19	} from 'node:crypto';
20	import { constants as fsConstants, readFileSync, realpathSync } from 'node:fs';
21	import { access, mkdir, readdir, readFile, realpath, rename, rm, stat, writeFile } from 'node:fs/promises';
22	import { basename, dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
23	import { fileURLToPath } from 'node:url';
24	
25	export const PROOF_VERSION = '1.0';
26	
27	// ---------------------------------------------------------------------------
28	// 错误类型：携带机器可读错误码，CLI 边界统一转换为非零退出。
29	// ---------------------------------------------------------------------------
30	
31	export const ERROR_CODES = Object.freeze({
32	  INPUT_NOT_FOUND: 'INPUT_NOT_FOUND',
33	  PERMISSION_DENIED: 'PERMISSION_DENIED',
34	  PROOF_INVALID: 'PROOF_INVALID',
35	  SIGNATURE_INVALID: 'SIGNATURE_INVALID',
36	  KEY_NOT_FOUND: 'KEY_NOT_FOUND',
37	  INTEGRITY_MISMATCH: 'INTEGRITY_MISMATCH',
38	  POLICY_INVALID: 'POLICY_INVALID',
39	  POLICY_VIOLATION: 'POLICY_VIOLATION',
40	  SYMLINK_INVALID: 'SYMLINK_INVALID',
41	  USAGE_ERROR: 'USAGE_ERROR',
42	});
43	
44	class ProvError extends Error {
45	  constructor(code, message, details) {
46	    super(message);
47	    this.name = 'ProvError';
48	    this.code = code;
49	    if (details !== undefined) this.details = details;
50	  }
51	}
52	
53	// 把 Node 底层错误归类为 INPUT_NOT_FOUND / PERMISSION_DENIED，其余原样抛出。
54	function wrapFsError(err, context) {
55	  if (err instanceof ProvError) return err;
56	  const where = context ? `${context}: ` : '';
57	  if (err && err.code === 'ENOENT') {
58	    return new ProvError(ERROR_CODES.INPUT_NOT_FOUND, `${where}路径不存在 (${err.path || 'unknown path'})`);
59	  }
60	  if (err && (err.code === 'EACCES' || err.code === 'EPERM')) {
61	    return new ProvError(ERROR_CODES.PERMISSION_DENIED, `${where}权限不足 (${err.path || 'unknown path'})`);
62	  }
63	  return err;
64	}
65	
66	// ---------------------------------------------------------------------------
67	// 路径与摘要工具
68	// ---------------------------------------------------------------------------
69	
70	// 清单中的相对路径统一使用正斜杠，保证跨平台稳定。
71	export function toPosix(relPath) {
72	  return relPath.split(sep).join('/');
73	}
74	
75	// 稳定哈希：SHA-256，摘要对象按 key 排序后以 UTF-8 序列化（两空格缩进）。
76	export function stableJsonStringify(value) {
77	  return JSON.stringify(sortDeep(value), null, 2);
78	}
79	
80	function sortDeep(value) {
81	  if (Array.isArray(value)) return value.map(sortDeep);
82	  if (value !== null && typeof value === 'object') {
83	    const out = {};
84	    for (const key of Object.keys(value).sort()) out[key] = sortDeep(value[key]);
85	    return out;
86	  }
87	  return value;
88	}
89	
90	export function sha256Hex(data) {
91	  return createHash('sha256').update(data).digest('hex');
92	}
93	
94	// 公钥指纹：对 SPKI 编码的 DER 字节取 SHA-256。写入证明并随证明一起签名，
95	// 验证时据此区分“使用了错误公钥”（指纹不一致）与“签名内容被篡改”（指纹一致但验签失败）。
96	export function keyFingerprint(keyObj) {
97	  return sha256Hex(keyObj.export({ type: 'spki', format: 'der' }));
98	}
99	
100	// ---------------------------------------------------------------------------
101	// 产物扫描：递归列出全部常规文件（含符号链接解引用后的目标），
102	// 空目录自然产生空清单；零字节文件按真实文件记录。
103	// 符号链接安全规则（按真实路径判定）：
104	//   - 目标越出产物根目录                 -> SYMLINK_INVALID / outside-root；
105	//   - 目标为当前递归祖先链上的目录（含根目录自身），或链接互相成环（ELOOP）
106	//                                        -> SYMLINK_INVALID / cycle；
107	//   - 指向根目录内部普通文件/目录的链接按链接路径记录目标内容；
108	//     祖先链之外的重复目标允许展开（有向无环，不会形成回路）。
109	// 判定在读取目标内容之前完成，危险链接不会被解引用读取。
110	// ---------------------------------------------------------------------------
111	
112	// 符号链接安全检查失败：携带相对路径与原因（cycle / outside-root）。
113	function symlinkError(fullPath, rootDir, reason) {
114	  const relPath = toPosix(relative(rootDir, fullPath));
115	  const message =
116	    reason === 'cycle'
117	      ? `符号链接形成回路: ${relPath}`
118	      : `符号链接越出产物根目录: ${relPath}`;
119	  return new ProvError(ERROR_CODES.SYMLINK_INVALID, message, { path: relPath, reason });
120	}
121	
122	// 解析真实路径；底层错误按既有归类转换。
123	async function realPathOf(p, context) {
124	  try {
125	    return await realpath(p);
126	  } catch (err) {
127	    throw wrapFsError(err, context);
128	  }
129	}
130	
131	async function walkFiles(rootDir) {
132	  const found = [];
133	  const rootReal = await realPathOf(rootDir, '读取产物目录');
134	  // chain 为当前递归路径上各级目录的真实路径，用于识别指回祖先的链接回路。
135	  async function walk(dir, chain) {
136	    let entries;
137	    try {
138	      entries = await readdir(dir, { withFileTypes: true });
139	    } catch (err) {
140	      throw wrapFsError(err, '读取产物目录');
141	    }
142	    for (const entry of entries) {
143	      const full = join(dir, entry.name);
144	      if (entry.isDirectory()) {
145	        await walk(full, [...chain, await realPathOf(full, '读取产物目录')]);
146	      } else if (entry.isFile()) {
147	        found.push(full);
148	      } else if (entry.isSymbolicLink()) {
149	        // 先解析真实目标并做安全判定，再按目标类型处理：
150	        // 指向目录则继续递归，指向文件则按链接路径记录。
151	        let targetReal;
152	        try {
153	          targetReal = await realpath(full);
154	        } catch (err) {
155	          // 链接互相指向成环（如 a -> b、b -> a）时 realpath 报 ELOOP。
156	          if (err && err.code === 'ELOOP') throw symlinkError(full, rootDir, 'cycle');
157	          throw wrapFsError(err, '读取符号链接');
158	        }
159	        if (!isWithin(targetReal, rootReal)) {
160	          throw symlinkError(full, rootDir, 'outside-root');
161	        }
162	        if (chain.includes(targetReal)) {
163	          throw symlinkError(full, rootDir, 'cycle');
164	        }
165	        let target;
166	        try {
167	          target = await stat(full);
168	        } catch (err) {
169	          throw wrapFsError(err, '读取符号链接');
170	        }
171	        if (target.isDirectory()) await walk(full, [...chain, targetReal]);
172	        else if (target.isFile()) found.push(full);
173	      }
174	      // 其他特殊文件（套接字/设备等）忽略。
175	    }
176	  }
177	  await walk(rootDir, [rootReal]);
178	  return found;
179	}
180	
181	// 判断 root 是否位于 outDir 之内（用于从扫描结果排除输出目录自身）。
182	function isWithin(pathAbs, dirAbs) {
183	  const relPath = relative(dirAbs, pathAbs);
184	  return relPath === '' || (!!relPath && !relPath.startsWith('..') && !isAbsolute(relPath));
185	}
186	
187	async function fileTypeFromPath(fullPath, data) {
188	  // 极简魔数嗅探，仅用于清单的 type 字段；不识别时回退为扩展名或 "data"。
189	  // 一律使用字节数组，避免多字节字符串经 UTF-8 编码后长度/取值不符。
190	  const startsWith = (bytes) =>
191	    data.length >= bytes.length && bytes.every((b, i) => data[i] === b);
192	  if (startsWith([0x1f, 0x8b])) return 'application/gzip';
193	  if (startsWith([0x50, 0x4b, 0x03, 0x04])) return 'application/zip';
194	  if (startsWith([0x25, 0x50, 0x44, 0x46, 0x2d])) return 'application/pdf'; // %PDF-
195	  if (startsWith([0x7f, 0x45, 0x4c, 0x46])) return 'application/x-elf';
196	  if (startsWith([0x4d, 0x5a])) return 'application/x-dosexec'; // MZ
197	  if (startsWith([0xff, 0xd8, 0xff])) return 'image/jpeg';
198	  if (startsWith([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image/png';
199	  // 类脚本/文本：UTF BOM，或前 512 字节不含 NUL 则视为 text。
200	  if (
201	    startsWith([0xef, 0xbb, 0xbf]) ||
202	    startsWith([0xff, 0xfe]) ||
203	    startsWith([0xfe, 0xff])
204	  ) {
205	    return 'text/plain';
206	  }
207	  if (!data.subarray(0, 512).includes(0)) return 'text/plain';
208	  const ext = basename(fullPath).split('.').pop();
209	  return ext && ext !== basename(fullPath) ? `application/x-${ext.toLowerCase()}` : 'application/octet-stream';
210	}
211	
212	// 构建 SBOM。时间字段不进入清单，文件摘要只依赖文件字节与相对路径。
213	// excludeDir 为输出目录的绝对路径（若位于产物内部则排除）。
214	export async function buildSbom(artifactPath, excludeDir) {
215	  const artifactAbs = resolve(artifactPath);
216	  let artifactStat;
217	  try {
218	    artifactStat = await stat(artifactAbs);
219	  } catch (err) {
220	    throw wrapFsError(err, '读取产物');
221	  }
222	
223	  const rootDir = artifactStat.isDirectory() ? artifactAbs : dirname(artifactAbs);
224	  const excludeAbs = excludeDir ? resolve(excludeDir) : null;
225	
226	  let files;
227	  if (artifactStat.isDirectory()) {
228	    files = await walkFiles(artifactAbs);
229	  } else {
230	    files = [artifactAbs];
231	  }
232	
233	  const entries = [];
234	  for (const full of files) {
235	    if (excludeAbs && isWithin(full, excludeAbs)) continue;
236	    let data;
237	    try {
238	      data = await readFile(full);
239	    } catch (err) {
240	      throw wrapFsError(err, '读取产物文件');
241	    }
242	    const relPath = toPosix(relative(rootDir, full));
243	    entries.push({
244	      path: relPath,
245	      sha256: sha256Hex(data),
246	      size: data.length,
247	      type: await fileTypeFromPath(full, data),
248	    });
249	  }
250	
251	  // 按相对路径排序，保证同一输入产生字节级一致的清单。
252	  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
253	
254	  return {
255	    schemaVersion: '1.0',
256	    artifactName: artifactStat.isDirectory() ? basename(artifactAbs) : basename(artifactAbs),
257	    rootType: artifactStat.isDirectory() ? 'directory' : 'file',
258	    files: entries,
259	  };
260	}
261	
262	// 顶层产物摘要：对“排序后的文件条目列表”做稳定哈希。
263	// 任何字节变化、文件新增/删除/重命名都会改变该摘要。
264	export function computeArtifactDigest(sbom) {
265	  return sha256Hex(stableJsonStringify(sbom.files));
266	}
267	
268	// ---------------------------------------------------------------------------
269	// 密钥与签名（Ed25519，PEM）
270	// ---------------------------------------------------------------------------
271	
272	function readPrivateKey(keyPath) {
273	  let pem;
274	  try {
275	    pem = readFileSync(keyPath);
276	  } catch (err) {
277	    throw wrapFsError(err, '读取私钥');
278	  }
279	  let keyObj;
280	  try {
281	    keyObj = createPrivateKey({ key: pem, format: 'pem' });
282	  } catch {
283	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `私钥无法解析或格式不受支持: ${keyPath}`);
284	  }
285	  if (keyObj.asymmetricKeyType !== 'ed25519') {
286	    throw new ProvError(
287	      ERROR_CODES.KEY_NOT_FOUND,
288	      `私钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
289	    );
290	  }
291	  return keyObj;
292	}
293	
294	function readPublicKey(keyPath) {
295	  let pem;
296	  try {
297	    pem = readFileSync(keyPath);
298	  } catch (err) {
299	    throw wrapFsError(err, '读取公钥');
300	  }
301	  let keyObj;
302	  try {
303	    keyObj = createPublicKey({ key: pem, format: 'pem' });
304	  } catch {
305	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `公钥无法解析或格式不受支持: ${keyPath}`);
306	  }
307	  if (keyObj.asymmetricKeyType !== 'ed25519') {
308	    throw new ProvError(
309	      ERROR_CODES.KEY_NOT_FOUND,
310	      `公钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
311	    );
312	  }
313	  return keyObj;
314	}
315	
316	// 生成阶段时间戳采用 UTC ISO-8601；它只写入 proof，不参与任何摘要。
317	function nowIso() {
318	  return new Date().toISOString();
319	}
320	
321	// ---------------------------------------------------------------------------
322	// keygen
323	// ---------------------------------------------------------------------------
324	
325	export async function keygen({ keyDir, name = 'provguard' }) {
326	  const absDir = resolve(keyDir);
327	  try {
328	    await mkdir(absDir, { recursive: true });
329	  } catch (err) {
330	    throw wrapFsError(err, '创建密钥目录');
331	  }
332	  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
333	  const privPath = join(absDir, `${name}.private.pem`);
334	  const pubPath = join(absDir, `${name}.public.pem`);
335	  try {
336	    await writeFile(
337	      privPath,
338	      privateKey.export({ type: 'pkcs8', format: 'pem' }),
339	      { mode: 0o600 },
340	    );
341	    await writeFile(
342	      pubPath,
343	      publicKey.export({ type: 'spki', format: 'pem' }),
344	      { mode: 0o644 },
345	    );
346	  } catch (err) {
347	    throw wrapFsError(err, '写入密钥');
348	  }
349	  return { privateKeyPath: privPath, publicKeyPath: pubPath };
350	}
351	
352	// ---------------------------------------------------------------------------
353	// generate
354	// ---------------------------------------------------------------------------
355	
356	export async function generate({ artifact, key, out }) {
357	  // 输入检查：产物与私钥必须存在且可读。
358	  const artifactAbs = resolve(artifact);
359	  const keyAbs = resolve(key);
360	  for (const [p, label] of [
361	    [artifactAbs, '产物'],
362	    [keyAbs, '私钥'],
363	  ]) {
364	    try {
365	      await access(p, fsConstants.R_OK);
366	    } catch (err) {
367	      throw wrapFsError(err, `读取${label}`);
368	    }
369	  }
370	
371	  const outAbs = resolve(out);
372	  const parent = dirname(outAbs);
373	  try {
374	    await mkdir(parent, { recursive: true });
375	  } catch (err) {
376	    throw wrapFsError(err, '创建输出目录');
377	  }
378	
379	  // 若输出目录尚不存在，先按真实路径创建，再据此排除。
380	  try {
381	    await mkdir(outAbs, { recursive: true });
382	  } catch (err) {
383	    throw wrapFsError(err, '创建输出目录');
384	  }
385	  let outReal;
386	  try {
387	    outReal = await realpath(outAbs);
388	  } catch (err) {
389	    throw wrapFsError(err, '解析输出目录');
390	  }
391	
392	  const privateKey = readPrivateKey(keyAbs);
393	  // 由私钥导出对应公钥，记录其指纹到证明中，供验证区分错误公钥与签名失配。
394	  const signingPublicKey = createPublicKey(privateKey);
395	  const signerKeyFingerprint = keyFingerprint(signingPublicKey);
396	
397	  const sbom = await buildSbom(artifactAbs, outReal);
398	  const artifactDigest = computeArtifactDigest(sbom);
399	
400	  // SBOM 规范字节：稳定 JSON（去尾换行后的 UTF-8）。proof 中的 sbomDigest 与
401	  // sbom.json.sig 绑定同一组字节，防止证明有效而 sbom.json 被整体替换。
402	  const sbomCanonical = stableJsonStringify(sbom);
403	  const sbomDigest = sha256Hex(sbomCanonical);
404	
405	  const proof = {
406	    proofVersion: PROOF_VERSION,
407	    artifactName: basename(artifactAbs),
408	    artifactDigest,
409	    fileName: basename(artifactAbs),
410	    size: sbom.files.reduce((n, f) => n + f.size, 0),
411	    generatedAt: nowIso(),
412	    signerKeyFingerprint,
413	    sbomDigest,
414	    files: sbom.files,
415	  };
416	  // 稳定字段顺序：proof 先按既定顺序构造，再整体排序输出。
417	  const proofJson = stableJsonStringify(proof) + '\n';
418	  const sbomJson = sbomCanonical + '\n';
419	
420	  // 对证明的规范字节（不含尾部换行）签名，验证时使用同一规范形式。
421	  // Ed25519 为纯签名算法，不接受摘要算法参数，故用 sign(null, data, key)。
422	  const signature = cryptoSign(null, Buffer.from(proofJson.trimEnd(), 'utf8'), privateKey);
423	  const signatureB64 = signature.toString('base64') + '\n';
424	  // 对 SBOM 规范字节单独签名，Base64 加换行保存。
425	  const sbomSignature = cryptoSign(null, Buffer.from(sbomCanonical, 'utf8'), privateKey);
426	  const sbomSignatureB64 = sbomSignature.toString('base64') + '\n';
427	
428	  const proofPath = join(outReal, 'proof.json');
429	  const sbomPath = join(outReal, 'sbom.json');
430	  const sigPath = join(outReal, 'proof.json.sig');
431	  const sbomSigPath = join(outReal, 'sbom.json.sig');
432	  try {
433	    await atomicWrite(proofPath, proofJson);
434	    await atomicWrite(sbomPath, sbomJson);
435	    await atomicWrite(sigPath, signatureB64);
436	    await atomicWrite(sbomSigPath, sbomSignatureB64);
437	  } catch (err) {
438	    throw wrapFsError(err, '写入证明产物');
439	  }
440	
441	  return {
442	    proofPath,
443	    sbomPath,
444	    signaturePath: sigPath,
445	    sbomSignaturePath: sbomSigPath,
446	    artifactDigest,
447	    sbomDigest,
448	    fileCount: sbom.files.length,
449	    proofVersion: PROOF_VERSION,
450	  };
451	}
452	
453	// 同目录临时文件 + rename，避免半成品证明文件留在输出目录。
454	async function atomicWrite(target, contents) {
455	  const dir = dirname(target);
456	  const tmp = join(dir, `.${basename(target)}.${process.pid}.tmp`);
457	  await writeFile(tmp, contents, { mode: 0o644 });
458	  try {
459	    await rename(tmp, target);
460	  } catch (err) {
461	    await rm(tmp, { force: true });
462	    throw err;
463	  }
464	}
465	
466	// ---------------------------------------------------------------------------
467	// verify
468	// ---------------------------------------------------------------------------
469	
470	export async function verify({
471	  artifact,
472	  proof: proofPath,
473	  signature: sigPath,
474	  key: pubKeyPath,
475	  sbom: sbomPath,
476	  sbomSignature: sbomSigPath,
477	  policy: policyPath,
478	}) {
479	  const artifactAbs = resolve(artifact);
480	  const proofAbs = resolve(proofPath);
481	  const sigAbs = resolve(sigPath);
482	  const keyAbs = resolve(pubKeyPath);
483	
484	  // --sbom 与 --sbom-signature 必须成对出现；只给一者是用法错误。
485	  const sbomMode = sbomPath !== undefined || sbomSigPath !== undefined;
486	  if (sbomMode && (sbomPath === undefined || sbomSigPath === undefined)) {
487	    throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
488	  }
489	  const sbomAbs = sbomMode ? resolve(sbomPath) : null;
490	  const sbomSigAbs = sbomMode ? resolve(sbomSigPath) : null;
491	
492	  // 1) 所有输入必须存在且可读。
493	  const inputs = [
494	    [artifactAbs, '产物'],
495	    [proofAbs, '证明文件'],
496	    [sigAbs, '签名文件'],
497	    [keyAbs, '公钥'],
498	  ];
499	  if (sbomMode) {
500	    inputs.push([sbomAbs, 'SBOM 文件'], [sbomSigAbs, 'SBOM 签名文件']);
501	  }
502	  for (const [p, label] of inputs) {
503	    try {
504	      await access(p, fsConstants.R_OK);
505	    } catch (err) {
506	      throw wrapFsError(err, `读取${label}`);
507	    }
508	  }
509	
