572	  try {
573	    sigOk = cryptoVerify(null, Buffer.from(canonicalProof, 'utf8'), publicKey, sigBuf);
574	  } catch {
575	    sigOk = false;
576	  }
577	  if (!sigOk) {
578	    throw new ProvError(
579	      ERROR_CODES.SIGNATURE_INVALID,
