719	function validateProof(proof) {
720	  if (proof === null || typeof proof !== 'object' || Array.isArray(proof)) {
721	    return '证明文件顶层必须是 JSON 对象';
722	  }
723	  const needString = ['proofVersion', 'artifactName', 'artifactDigest', 'fileName', 'generatedAt', 'signerKeyFingerprint'];
724	  for (const k of needString) {
725	    if (typeof proof[k] !== 'string' || proof[k].length === 0) {
726	      return `证明字段缺失或类型非法: ${k}`;
727	    }
728	  }
729	  if (!/^[0-9a-f]{64}$/i.test(proof.artifactDigest)) {
730	    return '证明中的 artifactDigest 不是合法的 SHA-256 十六进制摘要';
731	  }
732	  if (!/^[0-9a-f]{64}$/i.test(proof.signerKeyFingerprint)) {
733	    return '证明中的 signerKeyFingerprint 不是合法的 SHA-256 十六进制摘要';
734	  }
735	  if (typeof proof.size !== 'number' || !Number.isFinite(proof.size) || proof.size < 0) {
736	    return '证明字段缺失或类型非法: size';
737	  }
738	  if (!Array.isArray(proof.files)) return '证明字段缺失或类型非法: files';
739	  return validateFileEntries(proof.files);
740	}
741	
742	// 清单条目校验：proof.files 与 sbom.files 共用同一套规则。
743	function validateFileEntries(files) {
744	  const seen = new Set();
745	  for (const f of files) {
746	    if (f === null || typeof f !== 'object') return '清单条目必须是对象';
747	    if (typeof f.path !== 'string' || f.path.length === 0) return '清单条目 path 非法';
748	    if (f.path.includes('\\')) return `清单相对路径必须使用正斜杠: ${f.path}`;
749	    if (f.path.startsWith('/') || f.path.split('/').includes('..')) {
750	      return `清单相对路径越界: ${f.path}`;
751	    }
752	    if (seen.has(f.path)) return `清单路径重复: ${f.path}`;
753	    seen.add(f.path);
754	    if (!/^[0-9a-f]{64}$/i.test(f.sha256)) return `清单条目摘要非法: ${f.path}`;
755	    if (typeof f.size !== 'number' || !Number.isFinite(f.size) || f.size < 0) {
756	      return `清单条目大小非法: ${f.path}`;
757	    }
758	    if (typeof f.type !== 'string' || f.type.length === 0) return `清单条目类型非法: ${f.path}`;
759	  }
760	  return null;
761	}
762	
763	function validateSbom(sbom) {
764	  if (sbom === null || typeof sbom !== 'object' || Array.isArray(sbom)) {
765	    return 'SBOM 顶层必须是 JSON 对象';
766	  }
767	  for (const k of ['schemaVersion', 'artifactName', 'rootType']) {
768	    if (typeof sbom[k] !== 'string' || sbom[k].length === 0) {
769	      return `SBOM 字段缺失或类型非法: ${k}`;
770	    }
771	  }
772	  if (!Array.isArray(sbom.files)) return 'SBOM 字段缺失或类型非法: files';
773	  return validateFileEntries(sbom.files);
774	}
