812	// SBOM 清单与证明清单逐项比对；以证明为基准，kind 语义与 diffManifest 一致。
813	function diffSbomAgainstProof(sbom, proof) {
814	  const mismatches = [];
815	  const sbomFiles = new Map(sbom.files.map((f) => [f.path, f]));
816	  const proofFiles = new Map(proof.files.map((f) => [f.path, f]));
817	
818	  for (const [path, pf] of proofFiles) {
819	    const sf = sbomFiles.get(path);
820	    if (!sf) {
821	      mismatches.push({ path, kind: 'missing' }); // 证明中存在、SBOM 中缺失
822	      continue;
823	    }
824	    if (sf.sha256.toLowerCase() !== pf.sha256.toLowerCase()) {
825	      mismatches.push({ path, kind: 'content-modified' });
826	    } else if (sf.size !== pf.size) {
827	      mismatches.push({ path, kind: 'size-mismatch' });
828	    }
829	  }
830	  for (const path of sbomFiles.keys()) {
831	    if (!proofFiles.has(path)) {
832	      mismatches.push({ path, kind: 'added' }); // SBOM 中新出现的条目
833	    }
834	  }
835	  if (sbom.artifactName !== proof.artifactName) {
836	    mismatches.push({ path: '.', kind: 'artifact-name-mismatch' });
837	  }
838	
839	  mismatches.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : a.kind < b.kind ? -1 : 1));
