958	
959	  if (policy.requireSbom !== undefined && typeof policy.requireSbom !== 'boolean') {
960	    throw new ProvError(ERROR_CODES.POLICY_INVALID, '策略字段类型非法: requireSbom');
961	  }
962	  for (const k of ['maxFileCount', 'maxSize']) {
963	    if (policy[k] !== undefined && !isNonNegSafeInt(policy[k])) {
964	      throw new ProvError(ERROR_CODES.POLICY_INVALID, `策略字段取值非法: ${k}`);
965	    }
966	  }
967	
968	  // 时间区间不得倒置；相等（闭区间单点）允许。
969	  if (policy.proofNotBefore !== undefined && policy.proofNotAfter !== undefined) {
970	    if (parseUtcIso(policy.proofNotBefore) > parseUtcIso(policy.proofNotAfter)) {
971	      throw new ProvError(
972	        ERROR_CODES.POLICY_INVALID,
973	        '策略时间区间非法：proofNotBefore 晚于 proofNotAfter',
974	      );
975	    }
976	  }
977	
978	  return policy;
979	}
980	
981	// 在签名、完整性、可选 SBOM 校验全部通过后执行策略。
982	// 返回违规列表（已按时间、密钥、SBOM、文件数、大小排序）；空列表表示通过。
983	// 每条违规形如 { rule, observed }。
984	function evaluatePolicy(policy, proof, sbomMode) {
985	  const violations = [];
986	  const push = (rule, observed) => violations.push({ rule, observed });
987	
988	  // 1) 时间窗口：proof.generatedAt 必须落在闭区间；字段非法单独记。
989	  const generatedAtMs = parseUtcIso(proof.generatedAt);
990	  if (generatedAtMs === null) {
991	    push('generated-at-invalid', proof.generatedAt);
992	  } else {
993	    if (policy.proofNotBefore !== undefined && generatedAtMs < parseUtcIso(policy.proofNotBefore)) {
994	      push('proof-not-before', proof.generatedAt);
995	    }
996	    if (policy.proofNotAfter !== undefined && generatedAtMs > parseUtcIso(policy.proofNotAfter)) {
997	      push('proof-not-after', proof.generatedAt);
998	    }
999	  }
1000	
1001	  // 2) 密钥指纹必须命中白名单（大小写不敏感）。
1002	  if (policy.allowedKeyFingerprints !== undefined) {
1003	    const trusted = policy.allowedKeyFingerprints.map((fp) => fp.toLowerCase());
1004	    if (!trusted.includes(proof.signerKeyFingerprint.toLowerCase())) {
1005	      push('allowed-key-fingerprints', proof.signerKeyFingerprint);
1006	    }
1007	  }
1008	
1009	  // 3) requireSbom：必须成对提供 --sbom/--sbom-signature；其有效性已在前面校验。
1010	  //    requireSbom 为 false 时不禁用额外提供的 SBOM（沿用既有校验）。
1011	  if (policy.requireSbom === true && !sbomMode) {
1012	    push('require-sbom', 'absent');
1013	  }
1014	
1015	  // 4) 文件数上限。
1016	  if (policy.maxFileCount !== undefined && proof.files.length > policy.maxFileCount) {
1017	    push('max-file-count', proof.files.length);
1018	  }
1019	
1020	  // 5) 总大小上限。
1021	  if (policy.maxSize !== undefined && proof.size > policy.maxSize) {
1022	    push('max-size', proof.size);
1023	  }
1024	
1025	  return violations;
1026	}
1027	
1028	// ---------------------------------------------------------------------------
1029	// CLI
1030	// ---------------------------------------------------------------------------
1031	
1032	function parseArgs(argv) {
1033	  const args = { _: [] };
1034	  for (let i = 0; i < argv.length; i += 1) {
1035	    const a = argv[i];
1036	    if (a.startsWith('--')) {
1037	      const key = a.slice(2);
1038	      const next = argv[i + 1];
1039	      if (next === undefined || next.startsWith('--')) {
1040	        args[key] = true;
1041	      } else {
1042	        args[key] = next;
1043	        i += 1;
1044	      }
1045	    } else {
1046	      args._.push(a);
1047	    }
1048	  }
1049	  return args;
1050	}
1051	
1052	function usage() {
1053	  return [
1054	    'Prov Guard —— 软件供应链证明与完整性校验工具',
1055	    '',
1056	    '用法:',
1057	    '  provguard keygen   --key-dir <dir> [--name <prefix>]',
1058	    '  provguard generate --artifact <path> --key <private.pem> --out <dir>',
1059	    '  provguard verify   --artifact <path> --proof <proof.json> \\',
1060	    '                      --signature <proof.json.sig> --key <public.pem> \\',
1061	    '                      [--sbom <sbom.json> --sbom-signature <sbom.json.sig>] \\',
1062	    '                      [--policy <policy.json>]',
1063	    '',
1064	    'generate 输出: proof.json / proof.json.sig / sbom.json / sbom.json.sig',
1065	    '成功状态: VERIFIED；错误码见 README。',
1066	  ].join('\n');
1067	}
1068	
1069	function printMachineError(err) {
1070	  const payload = {
1071	    status: 'ERROR',
1072	    errorCode: err instanceof ProvError ? err.code : 'INTERNAL_ERROR',
1073	    message: err && err.message ? err.message : String(err),
1074	  };
1075	  if (err && err.details !== undefined) payload.details = err.details;
1076	  return stableJsonStringify(payload);
1077	}
1078	
1079	async function main(argv) {
1080	  const args = parseArgs(argv);
1081	  const command = args._[0];
1082	
1083	  try {
1084	    if (!command || command === 'help' || command === '--help' || command === '-h') {
1085	      process.stdout.write(`${usage()}\n`);
1086	      return 0;
1087	    }
1088	
1089	    if (command === 'keygen') {
1090	      if (!args['key-dir']) {
1091	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '缺少必填参数 --key-dir');
1092	      }
1093	      const r = await keygen({ keyDir: args['key-dir'], name: args.name || 'provguard' });
1094	      process.stdout.write(
1095	        `${stableJsonStringify({ status: 'KEYGEN_OK', ...r })}\n`,
1096	      );
1097	      return 0;
1098	    }
1099	
1100	    if (command === 'generate') {
1101	      const missing = ['artifact', 'key', 'out'].filter((k) => typeof args[k] !== 'string');
1102	      if (missing.length) {
1103	        throw new ProvError(
1104	          ERROR_CODES.USAGE_ERROR,
1105	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1106	        );
1107	      }
1108	      const r = await generate({ artifact: args.artifact, key: args.key, out: args.out });
1109	      process.stdout.write(
1110	        `${stableJsonStringify({
1111	          status: 'GENERATED',
1112	          proofVersion: r.proofVersion,
1113	          artifactDigest: r.artifactDigest,
1114	          fileCount: r.fileCount,
1115	          proofPath: r.proofPath,
1116	          sbomPath: r.sbomPath,
1117	          signaturePath: r.signaturePath,
1118	          sbomSignaturePath: r.sbomSignaturePath,
1119	        })}\n`,
1120	      );
1121	      return 0;
1122	    }
1123	
1124	    if (command === 'verify') {
1125	      const missing = ['artifact', 'proof', 'signature', 'key'].filter((k) => typeof args[k] !== 'string');
1126	      if (missing.length) {
1127	        throw new ProvError(
1128	          ERROR_CODES.USAGE_ERROR,
1129	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1130	        );
1131	      }
1132	      // --sbom 与 --sbom-signature 必须成对出现。
1133	      const hasSbom = typeof args.sbom === 'string';
1134	      const hasSbomSig = typeof args['sbom-signature'] === 'string';
1135	      if (hasSbom !== hasSbomSig) {
1136	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
1137	      }
1138	      // --policy 为可选单值参数；出现时必须带文件路径。
1139	      const hasPolicy = args.policy !== undefined;
1140	      if (hasPolicy && typeof args.policy !== 'string') {
1141	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--policy 需要提供策略文件路径');
1142	      }
1143	      const r = await verify({
1144	        artifact: args.artifact,
1145	        proof: args.proof,
1146	        signature: args.signature,
1147	        key: args.key,
1148	        sbom: hasSbom ? args.sbom : undefined,
1149	        sbomSignature: hasSbomSig ? args['sbom-signature'] : undefined,
1150	        policy: hasPolicy ? args.policy : undefined,
1151	      });
1152	      process.stdout.write(`${stableJsonStringify(r)}\n`);
1153	      return 0;
1154	    }
1155	
1156	    throw new ProvError(ERROR_CODES.USAGE_ERROR, `未知子命令: ${command}`);
1157	  } catch (err) {
1158	    // stderr 仅输出机器可读 JSON；用法帮助走 stdout，避免污染错误流。
1159	    process.stderr.write(`${printMachineError(err)}\n`);
1160	    if (err instanceof ProvError && err.code === ERROR_CODES.USAGE_ERROR) {
1161	      process.stdout.write(`\n${usage()}\n`);
1162	    }
1163	    return 1;
1164	  }
1165	}
1166	
1167	// 仅作为脚本直接运行时执行 main；被测试 import 时不执行。
1168	if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
1169	  main(process.argv.slice(2)).then((code) => {
1170	    process.exitCode = code;
1171	  });
1172	}
1173	
1174	export { main, ProvError, ERROR_CODES as CODES };
1175

